struct Wallet { var balance: Decimal?; var nickname: String? }

func describe(_ wallet: Wallet?) -> String {
    guard let wallet, let balance = wallet.balance else {   // Swift 5.7 shorthand
        return "Wallet unavailable"
    }
    let name = wallet.nickname ?? "Default"
    return "\(name): ₹\(balance)"
}

