enum PaymentError: Error, Equatable {
    case insufficientBalance(needed: Decimal)
    case declined
    case network
}

// Typed throws: callers know exactly what can come out
func payFromWallet(amount: Decimal, balance: Decimal) throws(PaymentError) -> Decimal {
    guard balance >= amount else { throw .insufficientBalance(needed: amount - balance) }
    return balance - amount
}

do {
    let left = try payFromWallet(amount: 120, balance: 80)
    print("Paid, ₹\(left) left")
} catch PaymentError.insufficientBalance(let needed) {
    print("Add ₹\(needed) to continue")
} catch {
    print("Payment failed: \(error)")
}

