// Hand-written equality: hash exactly what == compares
struct GeoPoint: Hashable {
    let lat: Double
    let lon: Double
    var label = ""                                     // not part of equality
    static func == (l: Self, r: Self) -> Bool { l.lat == r.lat && l.lon == r.lon }
    func hash(into h: inout Hasher) { h.combine(lat); h.combine(lon) }
}

