final class MachineViewModel {
    var socket: MachineSocket?

    func connect() {
        socket = MachineSocket()
        socket?.onMessage = { [weak self] message in   // break VM → socket → closure → VM
            guard let self else { return }
            self.handle(message)
        }
    }
    func handle(_ message: String) { }
    deinit { print("MachineViewModel freed") }       // proves the cycle is gone
}

struct Basket {
    private var storage = Storage()

    var items: [String] {
        get { storage.items }
        set {
            if !isKnownUniquelyReferenced(&storage) {   // shared? copy first
                storage = storage.copy()
            }
            storage.items = newValue
        }
    }

    final class Storage {
        var items: [String] = []
        func copy() -> Storage { let s = Storage(); s.items = items; return s }
    }
}

@MainActor @Observable
final class LiveTrayModel {
    var items: [TrayItem] = []
    private var pollTask: Task<Void, Never>?

    func start(api: TrayAPI) {
        // ❌ Leak: the task holds self strongly and never ends
        // pollTask = Task { while true { self.items = await api.tray(); try? await Task.sleep(for: .seconds(5)) } }

        // ✅ Weak self: once the screen releases the model, the loop exits
        pollTask = Task { [weak self] in
            while !Task.isCancelled {
                let latest = await api.tray()
                guard let self else { return }
                self.items = latest
                try? await Task.sleep(for: .seconds(5))
            }
        }
    }

    func stop() { pollTask?.cancel() }
    deinit { print("LiveTrayModel deinit") }       // DEBUG: proves the screen released it
}

