protocol Shape { func area() -> Double }
struct Circle: Shape { var r: Double; func area() -> Double { .pi * r * r } }

// Generic: can be specialised for Circle, calls resolved statically
func totalAreaGeneric<S: Shape>(_ shapes: [S]) -> Double {
    shapes.reduce(0) { $0 + $1.area() }
}

// Existential: each element boxed; area() goes through the witness table
func totalAreaExistential(_ shapes: [any Shape]) -> Double {
    shapes.reduce(0) { $0 + $1.area() }
}

