struct StoryPager: View {
    let stories: [Story]
    @State private var current: Story.ID?

    var body: some View {
        ScrollView(.horizontal) {
            LazyHStack(spacing: 0) {
                ForEach(stories) { story in
                    StoryCard(story: story)
                        .containerRelativeFrame(.horizontal)            // one per screen
                        .scrollTransition { content, phase in
                            content
                                .opacity(phase.isIdentity ? 1 : 0.6)
                                .scaleEffect(phase.isIdentity ? 1 : 0.92)
                        }
                }
            }
            .scrollTargetLayout()
        }
        .scrollTargetBehavior(.paging)
        .scrollPosition(id: $current)
        .onAppear { current = stories.first?.id }
        .overlay(alignment: .bottom) {
            let index = stories.firstIndex(where: { $0.id == current }) ?? 0
            Text("\(index + 1) / \(stories.count)")
                .padding(6)
                .background(.thinMaterial, in: Capsule())
        }
    }
}

