enum Route: Hashable {
    case machine(id: String)
    case product(sku: String)
    case orderDetail(UUID)
}

@Observable final class Router {
    var path = NavigationPath()
    func push(_ route: Route) { path.append(route) }
    func pop() { if !path.isEmpty { path.removeLast() } }
    func popToRoot() { path = NavigationPath() }
}

struct RootView: View {
    @State private var router = Router()

    var body: some View {
        NavigationStack(path: $router.path) {
            HomeView()
                .navigationDestination(for: Route.self) { route in
                    switch route {
                    case .machine(let id): MachineHomeView(machineID: id)
                    case .product(let sku): ProductView(sku: sku)
                    case .orderDetail(let id): OrderDetailView(orderID: id)
                    }
                }
        }
        .environment(router)       // HomeView: @Environment(Router.self) var router
    }
}

extension Router {
    // bbinstant://machine/BBI-0042   bbinstant://product/sku-991
    func handle(_ url: URL) {
        guard url.scheme == "bbinstant", let host = url.host() else { return }
        let parts = url.pathComponents.filter { $0 != "/" }
        switch (host, parts.first) {
        case ("machine", let id?):
            popToRoot(); push(.machine(id: id))
        case ("product", let sku?):
            push(.product(sku: sku))
        default:
            break                     // unknown link: stay where the user is
        }
    }
}

