enum CheckoutError: LocalizedError {
    case paymentDeclined, outOfStock(String)
    var errorDescription: String? {
        switch self {
        case .paymentDeclined: "Payment declined"
        case .outOfStock(let item): "\(item) just sold out"
        }
    }
    var recoverySuggestion: String? { "Your cart is saved. Try again or pick another item." }
}

