struct SwipeToPay: View {
    let amount: Decimal
    var onPay: () -> Void

    @GestureState private var drag: CGFloat = 0      // resets to 0 when the finger lifts
    @State private var paid = false
    private let trackWidth: CGFloat = 300
    private let knob: CGFloat = 56

    var body: some View {
        let maxX = trackWidth - knob
        let price = amount.formatted(.currency(code: "INR"))
        ZStack(alignment: .leading) {
            Capsule().fill(.green.opacity(0.15))
            Text(paid ? "Paid" : "Swipe to pay \(price)").frame(maxWidth: .infinity)
            Circle()
                .fill(.green)
                .frame(width: knob, height: knob)
                .offset(x: paid ? maxX : min(max(0, drag), maxX))
                .gesture(
                    DragGesture()
                        .updating($drag) { value, state, _ in state = value.translation.width }
                        .onEnded { value in
                            guard value.translation.width > maxX * 0.85 else { return }  // threshold
                            withAnimation(.snappy) { paid = true }
                            onPay()
                        }
                )
                .animation(.snappy, value: drag == 0)      // spring back on release
        }
        .frame(width: trackWidth, height: knob)
        .sensoryFeedback(.success, trigger: paid)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("Pay \(price)")
        .accessibilityAction { paid = true; onPay() }      // VoiceOver can't drag
    }
}

