// MVVM: methods mutate state directly
@MainActor @Observable
final class CartViewModel {
    private(set) var count = 0
    func addTapped() { count += 1 }
    func removeTapped() { count = max(0, count - 1) }
}

// Unidirectional (the idea behind TCA, without the library):
// state changes only inside a pure function of (state, action)
struct CartState: Equatable { var count = 0 }
enum CartAction { case addTapped, removeTapped }

func cartReducer(_ state: inout CartState, _ action: CartAction) {
    switch action {
    case .addTapped: state.count += 1
    case .removeTapped: state.count = max(0, state.count - 1)
    }
}

// Testing needs no mocks and no async: feed actions, check state
var state = CartState()
for action in [CartAction.addTapped, .removeTapped, .removeTapped] {
    cartReducer(&state, action)
}
assert(state == CartState(count: 0))

