protocol DiscountStrategy { func apply(to total: Decimal) -> Decimal }
struct NoDiscount: DiscountStrategy { func apply(to t: Decimal) -> Decimal { t } }
struct FlatOff: DiscountStrategy {
    let amount: Decimal
    func apply(to t: Decimal) -> Decimal { max(0, t - amount) }
}
