enum DoorEvent { case unlockRequested, unlockedAck, doorClosed, lockedAck }

enum DoorState: Equatable {
    case locked, unlocking, open(since: Date), closing

    mutating func handle(_ event: DoorEvent) {
        switch (self, event) {
        case (.locked, .unlockRequested): self = .unlocking
        case (.unlocking, .unlockedAck):  self = .open(since: .now)
        case (.open, .doorClosed):        self = .closing
        case (.closing, .lockedAck):      self = .locked
        default: break                    // event doesn't apply in this state
        }
    }
}

