// Repository: cached value first, then fresh
struct OrdersRepository: Sendable {
    let cache: OrderCache            // actor
    let remote: OrderRepository

    func orders() -> AsyncThrowingStream<[Order], Error> {
        AsyncThrowingStream { continuation in
            let task = Task {
                if let cached = await cache.load() { continuation.yield(cached) }   // instant
                do {
                    let fresh = try await remote.recentOrders()
                    await cache.save(fresh)
                    continuation.yield(fresh)                                       // then fresh
                    continuation.finish()
                } catch {
                    continuation.finish(throwing: error)
                }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }
}
