@MainActor
final class MachineScanner: NSObject, CBCentralManagerDelegate {
    private var central: CBCentralManager?
    private var continuation: AsyncStream<UUID>.Continuation?
    private let serviceID = CBUUID(string: "FFE0")            // your machine's service UUID

    func discover() -> AsyncStream<UUID> {
        AsyncStream { continuation in
            self.continuation = continuation
            self.central = CBCentralManager(delegate: self, queue: .main)
            continuation.onTermination = { [weak self] _ in
                Task { @MainActor in self?.central?.stopScan() }
            }
        }
    }

    // Callbacks arrive on the queue passed above (.main), so it's safe to assume main-actor isolation
    nonisolated func centralManagerDidUpdateState(_ central: CBCentralManager) {
        MainActor.assumeIsolated {
            switch central.state {
            case .poweredOn: central.scanForPeripherals(withServices: [serviceID])
            case .unauthorized, .poweredOff, .unsupported: continuation?.finish()   // UI explains why
            default: break
            }
        }
    }

    nonisolated func centralManager(_ central: CBCentralManager, didDiscover peripheral: CBPeripheral,
                                    advertisementData: [String: Any], rssi RSSI: NSNumber) {
        let id = peripheral.identifier
        MainActor.assumeIsolated { _ = continuation?.yield(id) }
    }
}

