final class RequestCounter: Sendable {
    private let count = Atomic<Int>(0)
    func next() -> Int { count.add(1, ordering: .relaxed).newValue }
}

final class TokenCache: Sendable {
    private let tokens = Mutex<[String: String]>([:])

    func token(for user: String) -> String? { tokens.withLock { $0[user] } }

    // ✅ check and act in one critical section
    func tokenOrInsert(_ user: String, make: () -> String) -> String {
        tokens.withLock { state in
            if let existing = state[user] { return existing }
            let new = make()
            state[user] = new
            return new
        }
    }
}

final class LegacyCache: Sendable {
    private let lock = OSAllocatedUnfairLock(initialState: [String: Data]())
    func value(_ key: String) -> Data? { lock.withLock { $0[key] } }
    func set(_ data: Data, _ key: String) { lock.withLock { $0[key] = data } }
}

