// Before: completion handler + main-queue hop
func loadOrders(completion: @escaping @Sendable (Result<[Order], Error>) -> Void) {
    DispatchQueue.global(qos: .userInitiated).async {
        let result = Result { try OrdersDisk.read() }
        DispatchQueue.main.async { completion(result) }
    }
}

// Step 1: async wrapper; callers migrate first
func loadOrders() async throws -> [Order] {
    try await withCheckedThrowingContinuation { continuation in
        loadOrders { continuation.resume(with: $0) }
    }
}

// Step 2: a serial queue guarding state becomes an actor
actor OrderStore {
    private var cache: [String: Order] = [:]
    func put(_ order: Order) { cache[order.id] = order }
    func get(_ id: String) -> Order? { cache[id] }
}

// Step 3: DispatchGroup fan-out becomes a TaskGroup with bounded width
func fetchReceipts(_ ids: [String], api: ReceiptAPI) async throws -> [Receipt] {
    try await withThrowingTaskGroup(of: Receipt.self) { group in
        var results: [Receipt] = []
        var pending = ids.makeIterator()
        for _ in 0..<4 {                                   // at most 4 in flight
            if let id = pending.next() { group.addTask { try await api.receipt(id) } }
        }
        while let receipt = try await group.next() {
            results.append(receipt)
            if let id = pending.next() { group.addTask { try await api.receipt(id) } }
        }
        return results
    }
}

