actor TokenRefresher {
    private var current: String?
    private var refreshTask: Task<String, Error>?

    func validToken() async throws -> String {
        if let current { return current }
        if let refreshTask { return try await refreshTask.value }   // join in-flight refresh

        let task = Task { try await AuthAPI.refresh() }
        refreshTask = task
        defer { refreshTask = nil }
        let token = try await task.value        // suspension: other callers may enter here
        current = token
        return token
    }

    func invalidate() { current = nil }
}

