// One-shot callback → async
func currentLocation(using fetcher: LocationFetcher) async throws -> Coordinate {
    try await withCheckedThrowingContinuation { continuation in
        fetcher.requestOnce { result in continuation.resume(with: result) }
    }
}

// Delegate with a single answer: keep the continuation, resume once, clear it
@MainActor
final class BluetoothStateReader: NSObject, CBCentralManagerDelegate {
    private var continuation: CheckedContinuation<CBManagerState, Never>?
    private var central: CBCentralManager?

    func currentState() async -> CBManagerState {
        await withCheckedContinuation { continuation in
            self.continuation = continuation
            self.central = CBCentralManager(delegate: self, queue: .main)
        }
    }

    nonisolated func centralManagerDidUpdateState(_ central: CBCentralManager) {
        let state = central.state
        MainActor.assumeIsolated {
            guard state != .unknown, state != .resetting else { return }   // wait for a real answer
            continuation?.resume(returning: state)
            continuation = nil                                             // never resume twice
        }
    }
}

// Cancellation doesn't resume a continuation for you
func download(_ url: URL, with sdk: VendorDownloader) async throws -> Data {
    let handle = sdk.makeHandle()
    return try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { continuation in
            handle.start(url) { continuation.resume(with: $0) }    // also called with .cancelled
        }
    } onCancel: {
        handle.cancel()
    }
}

struct Endpoint<Response: Decodable> {
    var path: String
    var method = "GET"
    var query: [URLQueryItem] = []
    var headers: [String: String] = [:]
    var body: Data? = nil

    func authorized(_ token: String) -> Self {
        var copy = self
        copy.headers["Authorization"] = "Bearer \(token)"
        return copy
    }
}

enum APIError: Error {
    case transport(URLError)
    case http(status: Int, body: Data)
    case decoding(Error)
    case unauthorized
}

protocol APIClient: Sendable {
    func send<R>(_ endpoint: Endpoint<R>) async throws -> R
}

struct URLSessionAPIClient: APIClient {
    var baseURL = URL(string: "https://api.example.com")!
    var session: URLSession = .shared

    func send<R>(_ endpoint: Endpoint<R>) async throws -> R {
        var components = URLComponents(url: baseURL.appending(path: endpoint.path),
                                       resolvingAgainstBaseURL: false)!
        if !endpoint.query.isEmpty { components.queryItems = endpoint.query }
        var request = URLRequest(url: components.url!)
        request.httpMethod = endpoint.method
        request.httpBody = endpoint.body
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        endpoint.headers.forEach { request.setValue($1, forHTTPHeaderField: $0) }

        let data: Data, response: URLResponse
        do { (data, response) = try await session.data(for: request) }
        catch let error as URLError { throw APIError.transport(error) }

        let status = (response as? HTTPURLResponse)?.statusCode ?? 0
        if status == 401 { throw APIError.unauthorized }
        guard (200..<300).contains(status) else { throw APIError.http(status: status, body: data) }
        do { return try JSONDecoder().decode(R.self, from: data) }
        catch { throw APIError.decoding(error) }
    }
}

