struct Product: Decodable, Identifiable, Equatable {
    let id: String
    let name: String
    let price: Decimal
    let expiresOn: Date?
    let tags: [String]

    enum CodingKeys: String, CodingKey {
        case id = "sku_id", name = "display_name", price = "mrp", expiresOn = "expiry", tags
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(String.self, forKey: .id)
        name = try c.decode(String.self, forKey: .name)

        let raw = try c.decode(String.self, forKey: .price)          // "49.50"
        guard let value = Decimal(string: raw) else {
            throw DecodingError.dataCorruptedError(
                forKey: .price, in: c, debugDescription: "Bad price \(raw)")
        }
        price = value
        expiresOn = try c.decodeIfPresent(Date.self, forKey: .expiresOn)
        tags = try c.decodeIfPresent([String].self, forKey: .tags) ?? []   // missing → []
    }
}

