struct AuthenticatedClient: APIClient {
    let base: APIClient
    let tokens: TokenRefresher

    func send<R>(_ endpoint: Endpoint<R>) async throws -> R {
        do {
            return try await base.send(endpoint.authorized(try await tokens.validToken()))
        } catch APIError.unauthorized {
            await tokens.invalidate()                // one refresh, one retry
            return try await base.send(endpoint.authorized(try await tokens.validToken()))
        }
    }
}

func withRetry<T>(attempts: Int = 3, _ operation: () async throws -> T) async throws -> T {
    var delay: Duration = .milliseconds(300)
    for attempt in 1... {
        do {
            return try await operation()
        } catch APIError.transport where attempt < attempts {
            try await Task.sleep(for: delay)        // throws CancellationError if cancelled
            delay *= 2
        }
    }
    fatalError("unreachable")
}

