// 2. Conditional requests: 304 = unchanged, nothing downloaded
actor CatalogCache {
    private var etag: String?
    private var products: [Product] = []
    private(set) var lastUpdated: Date?

    func cached() -> [Product] { products }

    func refresh(session: URLSession, url: URL) async throws -> [Product] {
        var request = URLRequest(url: url)
        request.cachePolicy = .reloadIgnoringLocalCacheData        // we validate ourselves
        if let etag { request.setValue(etag, forHTTPHeaderField: "If-None-Match") }

        let (data, response) = try await session.data(for: request)
        let http = response as? HTTPURLResponse
        switch http?.statusCode {
        case 304:
            lastUpdated = .now
        case 200:
            products = try JSONDecoder().decode([Product].self, from: data)
            etag = http?.value(forHTTPHeaderField: "ETag")
            lastUpdated = .now
        default:
            throw URLError(.badServerResponse)
        }
        return products
    }
}

