enum MachineEvent: Sendable, Decodable {
    case authenticated(sessionId: String)
    case door(opened: Bool)
    case itemPicked(productId: String, quantity: Int)
    case other(type: String)

    private enum Key: String, CodingKey { case type, sessionId, opened, productId, quantity }
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: Key.self)
        let type = try c.decode(String.self, forKey: .type)
        switch type {
        case "auth_success": self = .authenticated(sessionId: try c.decode(String.self, forKey: .sessionId))
        case "door_event":   self = .door(opened: try c.decode(Bool.self, forKey: .opened))
        case "item_picked":  self = .itemPicked(productId: try c.decode(String.self, forKey: .productId),
                                                quantity: try c.decodeIfPresent(Int.self, forKey: .quantity) ?? 1)
        default:             self = .other(type: type)
        }
    }
}

enum SocketError: Error { case stale, notLive }

actor MachineSession {
    enum State: Sendable, Equatable { case idle, connecting, live, waiting(retryIn: Duration), failed, stopped }

    let events: AsyncStream<MachineEvent>          // one stream, created once
    private let sink: AsyncStream<MachineEvent>.Continuation
    private(set) var state: State = .idle

    private let url: URL
    private let machineID: String
    private let token: @Sendable () async throws -> String
    private var supervisor: Task<Void, Never>?
    private var socket: URLSessionWebSocketTask?
    private var failures = 0
    private var lastFrame = ContinuousClock.now

    init(url: URL, machineID: String, token: @escaping @Sendable () async throws -> String) {
        let (stream, continuation) = AsyncStream.makeStream(of: MachineEvent.self,
                                                            bufferingPolicy: .bufferingNewest(100))
        events = stream; sink = continuation
        self.url = url; self.machineID = machineID; self.token = token
    }

    func start() {
        guard supervisor == nil else { return }
        supervisor = Task { await supervise() }
    }

    func stop() {
        supervisor?.cancel(); supervisor = nil
        socket?.cancel(with: .normalClosure, reason: nil); socket = nil
        state = .stopped
        sink.finish()                              // ends the consumer's for-await loop
    }

    func send(_ command: Command) async throws {
        guard let socket, state == .live else { throw SocketError.notLive }
        try await send(command, on: socket)
    }

    // Owns the lifecycle: connect → run until something fails → back off → repeat
    private func supervise() async {
        while !Task.isCancelled {
            state = .connecting
            let task = URLSession.shared.webSocketTask(with: url)
            socket = task
            lastFrame = .now
            task.resume()
            do { try await run(task) } catch { /* fall through to reconnect */ }
            task.cancel(with: .goingAway, reason: nil)
            guard !Task.isCancelled else { return }

            failures += 1
            if failures > 8 { state = .failed; sink.finish(); return }
            let delay = backoff(failures)
            state = .waiting(retryIn: delay)
            try? await Task.sleep(for: delay)
        }
    }

    private func run(_ task: URLSessionWebSocketTask) async throws {
        try await send(.auth(try await token(), machine: machineID), on: task)
        try await withThrowingTaskGroup(of: Void.self) { group in
            group.addTask { try await self.receiveLoop(task) }
            group.addTask { try await self.heartbeatLoop(task) }
            try await group.next()                 // first child to finish or throw ends both
            group.cancelAll()
        }
    }

    private func receiveLoop(_ task: URLSessionWebSocketTask) async throws {
        while true {
            let frame = try await task.receive()   // throws when the socket closes
            lastFrame = .now
            guard case .string(let text) = frame,
                  let event = try? JSONDecoder().decode(MachineEvent.self, from: Data(text.utf8))
            else { continue }
            if case .authenticated = event { state = .live; failures = 0 }   // reset only on real auth
            sink.yield(event)
        }
    }

    private func heartbeatLoop(_ task: URLSessionWebSocketTask) async throws {
        while true {
            try await Task.sleep(for: .seconds(15))
            if ContinuousClock.now - lastFrame > .seconds(45) { throw SocketError.stale }  // half-open
            try await send(.heartbeat, on: task)   // server replies heartbeat_ack, refreshing lastFrame
        }
    }

    private func send(_ command: Command, on task: URLSessionWebSocketTask) async throws {
        let json = String(decoding: try JSONEncoder().encode(command), as: UTF8.self)
        try await task.send(.string(json))
    }

    private func backoff(_ failures: Int) -> Duration {
        let seconds = min(30.0, pow(2.0, Double(failures)))           // 2, 4, 8, 16, 30…
        return .milliseconds(Int(seconds * 1000 * Double.random(in: 0.5...1)))   // jitter
    }
}

