// The reconnect fix as applied in MachineSocket.swift (excerpt)
private func scheduleReconnect() {
    guard let machineId = currentMachineId, reconnectTask == nil else { return }

    reconnectAttempt += 1
    guard reconnectAttempt <= maxReconnectAttempts else {
        closeSocket(code: .goingAway)
        reconnectAttempt = 0
        connectionState = .failed("Max reconnect attempts reached")
        return
    }

    let attempt = reconnectAttempt
    connectionState = .reconnecting(attempt: attempt)
    let delay = min(pow(2.0, Double(attempt)), 30.0)

    reconnectTask = Task {                       // its own task: nothing it calls can cancel it
        try? await Task.sleep(for: .seconds(delay))
        guard !Task.isCancelled else { return }
        await self.reconnect(machineId: machineId)
    }
}

private func reconnect(machineId: String) async {
    reconnectTask = nil
    closeSocket(code: .goingAway)                // keeps machine id and attempt count
    connectionState = .disconnected
    await connect(machineId: machineId)
}

