import CoreData

@MainActor
final class Persistence {
    let container: NSPersistentContainer

    init() {
        container = NSPersistentContainer(name: "Orders")
        let description = container.persistentStoreDescriptions.first
        description?.shouldMigrateStoreAutomatically = true       // lightweight migration
        description?.shouldInferMappingModelAutomatically = true
        container.loadPersistentStores { _, error in
            if let error { print("Store failed to load: \(error)") }   // recover in production
        }
        container.viewContext.automaticallyMergesChangesFromParent = true
        container.viewContext.mergePolicy = NSMergePolicy.mergeByPropertyObjectTrump
    }

    // Import many rows off the main thread in one batch
    func importOrders(_ dtos: [OrderDTO]) async throws {
        let context = container.newBackgroundContext()
        let ids = try await context.perform {                  // runs on the context's own queue
            let rows: [[String: Any]] = dtos.map {
                ["id": $0.id, "machineName": $0.machineName, "placedAt": $0.placedAt]
            }
            let request = NSBatchInsertRequest(entityName: "CachedOrder", objects: rows)
            request.resultType = .objectIDs
            let result = try context.execute(request) as? NSBatchInsertResult
            return result?.result as? [NSManagedObjectID] ?? []
        }
        // Batch inserts bypass contexts: tell the UI context what changed (back on the main actor)
        NSManagedObjectContext.mergeChanges(fromRemoteContextSave: [NSInsertedObjectsKey: ids],
                                            into: [container.viewContext])
    }
}

