@MainActor @Observable
final class CatalogModel {
    var products: [Product] = []

    // Before: decoding a 2 MB catalog on the main actor freezes scrolling
    func applyBlocking(_ data: Data) throws {
        products = try JSONDecoder().decode([Product].self, from: data)
    }

    // After: decode on the concurrent pool, hop back only to assign
    func apply(_ data: Data) async throws {
        products = try await Self.decode(data)
    }

    @concurrent
    nonisolated static func decode(_ data: Data) async throws -> [Product] {
        try JSONDecoder().decode([Product].self, from: data)
    }
}

