import UIKit

enum Thumbnails {
    // NSCache is thread-safe, which the compiler can't see
    nonisolated(unsafe) static let cache: NSCache<NSURL, UIImage> = {
        let cache = NSCache<NSURL, UIImage>()
        cache.totalCostLimit = 60 * 1024 * 1024        // ~60 MB of decoded pixels
        return cache
    }()

    static func store(_ image: UIImage, for url: URL) {
        let pixels = image.size.width * image.scale * image.size.height * image.scale
        cache.setObject(image, forKey: url as NSURL, cost: Int(pixels * 4))
    }
}

