import LocalAuthentication

func unlockWallet() async -> Bool {
    let context = LAContext()
    var error: NSError?
    guard context.canEvaluatePolicy(.deviceOwnerAuthentication, error: &error) else { return false }
    do {
        return try await context.evaluatePolicy(.deviceOwnerAuthentication,
                                                localizedReason: "Unlock your bb Wallet")
    } catch {
        return false                          // cancelled or failed: keep the balance hidden
    }
}

// A secret readable only while the device owner is present
func saveWalletPIN(_ pin: String) throws {
    let base: [String: Any] = [
        kSecClass as String: kSecClassGenericPassword,
        kSecAttrAccount as String: "wallet.pin"
    ]
    SecItemDelete(base as CFDictionary)                       // delete by identity only

    guard let access = SecAccessControlCreateWithFlags(
        nil, kSecAttrAccessibleWhenPasscodeSetThisDeviceOnly, .userPresence, nil) else { return }
    var item = base
    item[kSecValueData as String] = Data(pin.utf8)
    item[kSecAttrAccessControl as String] = access
    let status = SecItemAdd(item as CFDictionary, nil)
    guard status == errSecSuccess else { throw KeychainError(status: status) }
}

