    func summarise(_ reviews: [String]) async {
        let model = SystemLanguageModel.default
        guard case .available = model.availability else {
            message = "On-device summaries need Apple Intelligence on this device."
            return
        }
        let session = LanguageModelSession(instructions: "You summarise vending machine reviews for an operations team.")
        do {
            let response = try await session.respond(
                to: "Summarise these reviews:\n" + reviews.joined(separator: "\n"),
