@MainActor @Observable
final class Membership {
    private(set) var products: [Product] = []
    private(set) var isMember = false
    private var updates: Task<Void, Never>?

    func start() {
        updates = Task {                                   // renewals, refunds, Ask to Buy, other devices
            for await result in StoreKit.Transaction.updates { await handle(result) }
        }
    }

    func load() async {
        products = (try? await Product.products(for: ["instant.plus.monthly", "instant.plus.yearly"])) ?? []
        for await result in StoreKit.Transaction.currentEntitlements { await handle(result) }
    }

    func buy(_ product: Product) async throws {
        switch try await product.purchase() {
        case .success(let verification): await handle(verification)
        case .pending, .userCancelled: break
        @unknown default: break
        }
    }

    private func handle(_ result: VerificationResult<StoreKit.Transaction>) async {
        guard case .verified(let transaction) = result else { return }   // ignore unverified receipts
        isMember = transaction.revocationDate == nil
        await transaction.finish()                                         // always finish
    }
}

