@preconcurrency import UserNotifications     // the SDK predates Sendable annotations
import UIKit

final class PushRouter: NSObject, UNUserNotificationCenterDelegate {
    func register() async throws {
        let center = UNUserNotificationCenter.current()
        center.delegate = self
        let granted = try await center.requestAuthorization(options: [.alert, .sound, .badge])
        if granted { await MainActor.run { UIApplication.shared.registerForRemoteNotifications() } }

        let reorder = UNNotificationAction(identifier: "REORDER", title: "Reorder", options: [.foreground])
        let category = UNNotificationCategory(identifier: "ORDER_DONE", actions: [reorder], intentIdentifiers: [])
        center.setNotificationCategories([category])
    }

    // App in foreground: decide how to show it
    func userNotificationCenter(_ center: UNUserNotificationCenter, willPresent notification: UNNotification) async
        -> UNNotificationPresentationOptions {
        [.banner, .sound]
    }

    // User tapped the notification or an action
    func userNotificationCenter(_ center: UNUserNotificationCenter, didReceive response: UNNotificationResponse) async {
        let info = response.notification.request.content.userInfo
        guard let link = info["deeplink"] as? String, let url = URL(string: link) else { return }
        await MainActor.run { DeepLinks.open(url, action: response.actionIdentifier) }
    }
}

@MainActor enum DeepLinks { static func open(_ url: URL, action: String) {} }

// Notification Service Extension: edit the content before it is shown
// (payload must include "mutable-content": 1)
final class NotificationService: UNNotificationServiceExtension {
    private var contentHandler: ((UNNotificationContent) -> Void)?
    private var bestAttempt: UNMutableNotificationContent?

    override func didReceive(_ request: UNNotificationRequest,
                             withContentHandler contentHandler: @escaping (UNNotificationContent) -> Void) {
        self.contentHandler = contentHandler
        bestAttempt = request.content.mutableCopy() as? UNMutableNotificationContent
        guard let bestAttempt,
              let urlString = request.content.userInfo["image"] as? String,
              let url = URL(string: urlString) else { return contentHandler(request.content) }

        Task {
            if let (location, _) = try? await URLSession.shared.download(from: url) {
                let file = FileManager.default.temporaryDirectory.appending(path: url.lastPathComponent)
                try? FileManager.default.moveItem(at: location, to: file)
                if let image = try? UNNotificationAttachment(identifier: "image", url: file) {
                    bestAttempt.attachments = [image]
                }
            }
            contentHandler(bestAttempt)
        }
    }

    // ~30 s budget exceeded: deliver whatever we have
    override func serviceExtensionTimeWillExpire() {
        if let contentHandler, let bestAttempt { contentHandler(bestAttempt) }
    }
}

