@MainActor @Observable
final class Store<State, Action: Sendable> {
    private(set) var state: State
    private let reduce: (inout State, Action) -> Effect<Action>

    init(_ initial: State, reduce: @escaping (inout State, Action) -> Effect<Action>) {
        state = initial
        self.reduce = reduce
    }

    func send(_ action: Action) {
        let effect = reduce(&state, action)          // pure, synchronous change
        guard let run = effect.run else { return }
        Task { if let next = await run() { send(next) } }   // effect feeds back an action
    }
}

struct Effect<Action: Sendable> {
    var run: (@Sendable () async -> Action?)?
    static var none: Effect { Effect(run: nil) }
}

enum PlayerAction: Sendable { case playTapped, buffered(Bool) }
struct PlayerState { var isBuffering = false; var isPlaying = false }

let player = Store<PlayerState, PlayerAction>(PlayerState()) { state, action in
    switch action {
    case .playTapped:
        state.isBuffering = true
        return Effect { .buffered(await Prefetch.firstSegmentReady()) }
    case .buffered(let ok):
        state.isBuffering = false
        state.isPlaying = ok
        return .none
    }
}

@MainActor @Observable
final class FeedModel {                              // UI state: main actor
    var posts: [Post] = []
    let images = ImagePipeline()                     // shared cache: its own actor

    func load(api: FeedAPI) async throws {
        let data = try await api.feedData()          // network: suspends, never blocks main
        posts = try await Self.decode(data)          // parse on the concurrent pool
    }

    @concurrent nonisolated static func decode(_ data: Data) async throws -> [Post] {
        try JSONDecoder().decode([Post].self, from: data)
    }
}

actor ImagePipeline {
    private var cache: [URL: UIImage] = [:]
    private var inFlight: [URL: Task<UIImage?, Never>] = [:]

    func image(for url: URL) async -> UIImage? {
        if let hit = cache[url] { return hit }
        if let running = inFlight[url] { return await running.value }   // de-duplicate
        let task = Task { () -> UIImage? in
            guard let (data, _) = try? await URLSession.shared.data(from: url) else { return nil }
            return await downsample(data, to: CGSize(width: 160, height: 240), scale: 3)
        }
        inFlight[url] = task
        let image = await task.value
        inFlight[url] = nil
        cache[url] = image
        return image
    }
}

