@MainActor @Observable
final class PlayerModel {
    let player = AVPlayer()
    private(set) var seconds: Double = 0
    private var timeToken: Any?

    func play(_ url: URL) {
        player.replaceCurrentItem(with: AVPlayerItem(url: url))   // HLS: bitrate adapts automatically
        timeToken = player.addPeriodicTimeObserver(
            forInterval: CMTime(seconds: 0.5, preferredTimescale: 600), queue: .main
        ) { [weak self] time in
            MainActor.assumeIsolated { self?.seconds = time.seconds }
        }
        player.play()
    }

    func stop() {
        player.pause()
        if let timeToken { player.removeTimeObserver(timeToken) }
        timeToken = nil
    }
}

