actor ProgressStore {
    private var pending: [String: Double] = [:]          // episode id → seconds
    private var lastFlush = ContinuousClock.now
    private let api: ProgressAPI
    init(api: ProgressAPI) { self.api = api }

    func record(_ seconds: Double, episode: String) async {
        pending[episode] = seconds
        if ContinuousClock.now - lastFlush > .seconds(10) { await flush() }
    }

    func flush() async {                                  // also on pause and scenePhase == .background
        let batch = pending
        pending = [:]
        lastFlush = .now
        for (id, seconds) in batch {
            do { try await api.save(episode: id, seconds: seconds) }
            catch { if pending[id] == nil { pending[id] = seconds } }   // retry later unless superseded
        }
    }
}

