@MainActor @Observable
final class FeedPager {
    private(set) var videos: [Video] = []
    private(set) var isLoading = false
    private var cursor: String?
    private var reachedEnd = false
    private let api: FeedAPI
    init(api: FeedAPI) { self.api = api }

    func loadMore(after current: Video? = nil) async {
        guard !isLoading, !reachedEnd else { return }
        if let current, !videos.suffix(5).contains(current) { return }   // prefetch 5 rows early
        isLoading = true
        defer { isLoading = false }
        do {
            let page = try await api.feed(after: cursor)
            let known = Set(videos.map(\.id))
            videos += page.items.filter { !known.contains($0.id) }
            cursor = page.nextCursor
            reachedEnd = page.nextCursor == nil
        } catch {
            // keep the cursor; the next row appearance retries
        }
    }
}
