final class UploadManager: Sendable {
    static let identifier = "com.example.video.uploads"

    private let session: URLSession = {                     // one background session, created once
        let config = URLSessionConfiguration.background(withIdentifier: UploadManager.identifier)
        config.sessionSendsLaunchEvents = true
        config.isDiscretionary = false
        return URLSession(configuration: config, delegate: UploadDelegate(), delegateQueue: nil)
    }()

    func upload(file: URL, to endpoint: URL, draftID: String) {
        var request = URLRequest(url: endpoint)
