final class UploadDelegate: NSObject, URLSessionTaskDelegate {
    func urlSession(_ session: URLSession, task: URLSessionTask, didSendBodyData sent: Int64,
                    totalBytesSent: Int64, totalBytesExpectedToSend: Int64) {
        let fraction = Double(totalBytesSent) / Double(max(totalBytesExpectedToSend, 1))
        let draft = task.taskDescription ?? ""
        Task { @MainActor in UploadProgress.shared.set(fraction, for: draft) }   // hop to main
    }
}

@MainActor @Observable
final class CartStore {
    private(set) var quantities: [String: Int] = [:]
    private var latest: [String: Int] = [:]               // sku → newest ticket
    private let api: CartAPI
    init(api: CartAPI) { self.api = api }

    func setQuantity(_ quantity: Int, for sku: String) async {
        let previous = quantities[sku, default: 0]
        quantities[sku] = quantity                         // optimistic
        let ticket = latest[sku, default: 0] + 1
        latest[sku] = ticket
        do {
            let confirmed = try await api.setQuantity(sku: sku, quantity: quantity)
            guard latest[sku] == ticket else { return }    // stale response: a newer tap won
            quantities[sku] = confirmed                    // server may clamp to stock
        } catch {
            guard latest[sku] == ticket else { return }
            quantities[sku] = previous                     // roll back, show a toast
        }
    }
}

