struct OutgoingMessage: Sendable, Codable, Identifiable {
    let id: UUID                     // client id: lets the server de-duplicate retries
    let chatID: String
    let text: String
    let createdAt: Date
}

actor Outbox {
    private var queue: [OutgoingMessage] = []
    private var flushing = false
    private let send: @Sendable (OutgoingMessage) async throws -> Void

    init(send: @escaping @Sendable (OutgoingMessage) async throws -> Void) { self.send = send }

    func enqueue(_ message: OutgoingMessage) async {
        queue.append(message)                     // persist to SwiftData here as well
        await flush()
    }

    func flush() async {                          // also call when the socket reconnects
        guard !flushing else { return }
        flushing = true
        defer { flushing = false }
        while let next = queue.first {
            do {
                try await send(next)
                queue.removeFirst()               // remove only after the server acks
            } catch {
                return                            // offline: keep order, retry later
            }
        }
    }
}

import ImageIO
import UIKit

@concurrent
func downsample(_ data: Data, to size: CGSize, scale: CGFloat) async -> UIImage? {
    let sourceOptions = [kCGImageSourceShouldCache: false] as CFDictionary
    guard let source = CGImageSourceCreateWithData(data as CFData, sourceOptions) else { return nil }
    let options = [
        kCGImageSourceCreateThumbnailFromImageAlways: true,
        kCGImageSourceShouldCacheImmediately: true,           // decode now, off main
        kCGImageSourceCreateThumbnailWithTransform: true,     // respect EXIF orientation
        kCGImageSourceThumbnailMaxPixelSize: max(size.width, size.height) * scale
    ] as CFDictionary
    guard let image = CGImageSourceCreateThumbnailAtIndex(source, 0, options) else { return nil }
    return UIImage(cgImage: image)
}
